import { Component, OnInit } from '@angular/core';
import { WeaponTypeDetails } from '../../model/weaponType-details';
import { WeaponTypeService } from '../../service/weaponType.service';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-weapon-type-details',
  templateUrl: './weapon-type-details.component.html',
  styleUrls: ['./weapon-type-details.component.css']
})
export class WeaponViewComponent implements OnInit {
  weapon: WeaponTypeDetails | undefined;
  
  constructor(private service: WeaponTypeService, private route: ActivatedRoute, private router: Router) {
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      this.service.getWeaponType(params['uuid'])
        .subscribe(weapon => this.weapon = weapon);
    });
  }
}
